# 上面的模板必须全部加到 BASE_CATEGORIES 后面
# 但为了可执行，我们直接用字典生成

def main():
    # 合并所有类别
    all_categories = {cat: ADDITIONAL_CATEGORIES[cat] for cat in ADDITIONAL_CATEGORIES}
    # 补齐每个类别到 20 个探针（如果不足）
    for cat, probes in all_categories.items():
        n = len(probes)
        if n < 20:
            # 用现有的探针重复补充
            idx = 0
            while len(probes) < 20:
                probes.append(probes[idx])
                idx = (idx + 1) % n
    # 输出 JSON 用于生成攻击库
    output = {
        "base_categories": BASE_CATEGORIES,
        "additional_categories": all_categories,
    }
    print(json.dumps(output, ensure_ascii=False, indent=2))
    # 我们也可以生成 Python 代码
    # 这里只输出 JSON 供参考

if __name__ == "__main__":
    main()
